#define _XOPEN_SOURCE 700

#include <stdlib.h>
#include <unistd.h>

/*
 * Plays Claude Code in the tests: a process with a known name that ends by
 * itself after the given seconds, so no test has to stop it. A copy of the
 * system sleep would do, but macOS kills copies of its platform binaries.
 */
int main(int argc, char **argv)
{
	unsigned left;

	left = argc > 1 ? (unsigned)atoi(argv[1]) : 1;
	while ((left = sleep(left)) > 0)
		;
	return 0;
}
